class U2AreasTest {
 @TempDir Path temp;ContenidoFixture x;AreasFixture f;NucleoU2 flow;
 @BeforeEach void setup()throws Exception{x=new ContenidoFixture(temp,Clock.systemUTC(),null);f=x.f;flow=f.core.u2();}
 @AfterEach void close()throws Exception{if(x!=null)x.close();}
 UUID req(UUID com){var sol=flow.distribuir(f.a(f.dist),UUID.randomUUID(),com,new Encaminar(0,new NuevoDestino("UPR","DEMO_SEDE_A",f.headA,"AREA_A"),"Evaluación regional sintética",null));return flow.asumir(f.a(f.headA),UUID.randomUUID(),sol.id(),new Asumir(0,f.profA,"Asunción regional","Domicilio no utilizable; decisión fundada con referencia sintética")).id();}
 void denied(int status,Runnable op){assertEquals(status,assertThrows(FalloTecnico.class,op::run).status);}
 @Test void principalNacidoEnU2DecidePertinenciaSinReinterpretarRegistroFirmado(){var com=x.d.nuevaWeb();var q=req(com);var c=flow.abrirCaso(f.a(f.headA),UUID.randomUUID(),q,new Apertura(0,f.profA,"Objetivo receptor de antecedentes")).id();var child=x.d.nuevaWeb();f.core.vincular(f.a(f.dist),UUID.randomUUID(),child,new Vinculacion(com,null,"Antecedente propuesto al REQ"));assertEquals("UPR",x.c().contextoReq(f.a(f.headA),q).get("unidad"));x.c().determinar(f.a(f.headA),UUID.randomUUID(),q,child,new ContenidoInstitucional.Pertinencia(0,List.of(c),true,"Pertinencia expresa por la principal institucional"));assertEquals("ASUNCION_SOL",x.d.db.sql.queryForObject("SELECT principal_origin FROM communication_pertinence_history WHERE child_id=?",String.class,child.toString()));assertEquals(0,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM authority_requirement_principal WHERE requirement_id=?",Long.class,q.toString()));denied(404,()->x.c().contextoReq(f.a(f.headB),q));}
 @Test void compartirReqNoEntregaOriginalesYLaGestionDocumentalPropiaSigueFuncionando()throws Exception{
  var original=x.original("ingreso-sintetico.pdf","application/pdf",false);var q=req(original.comunicacion());var a=flow.abrirCaso(f.a(f.headA),UUID.randomUUID(),q,new Apertura(0,f.profA,"Objetivo principal")).id();
  var proposal=flow.colaborar(f.a(f.headA),UUID.randomUUID(),q,new Colaborar(1,new NuevoDestino("UPR","DEMO_SEDE_A",f.headB,"AREA_B"),"Objetivo de área distinta"));flow.resolver(f.a(f.headB),UUID.randomUUID(),proposal.id(),new ResolverColaboracion(0,"ACEPTADA",f.profB,"Se acepta intervención limitada"));var b=UUID.fromString(x.d.db.sql.queryForObject("SELECT case_id FROM institution_collaboration WHERE id=?",String.class,proposal.id().toString()));
  assertNotNull(x.c().permisos(f.a(f.profA),a,original.documento()));denied(404,()->x.c().permisos(f.a(f.profB),b,original.documento()));denied(404,()->x.c().originalAutorizado(f.a(f.profB),original.comunicacion(),b));assertEquals(1,f.core.detalle(f.a(f.profA),original.comunicacion()).contenido().formularioCompleto().path("adjuntos").size());
  // La denegación del original compartido no impide crear un documento del Caso propio.
  var doc=x.docs.cargar(f.a(f.profB),UUID.randomUUID(),b,null,"propio.txt",new java.io.ByteArrayInputStream("Contenido propio sintético".getBytes(java.nio.charset.StandardCharsets.UTF_8))).id();assertNotNull(x.docs.referencia(f.a(f.profB),b,doc));assertEquals(q,f.core.caso(f.a(f.profB),b).requerimientoId());
 }
 @Test void reqRegionalConservaPrincipalConsultaMateriaNoDaGestionNiAccesoAlCom()throws Exception{var com=x.d.nuevaWeb();var q=req(com);var c=flow.abrirCaso(f.a(f.headA),UUID.randomUUID(),q,new Apertura(0,f.profA,"Objetivo regional independiente")).id();x.m.clasificar(c,0,"MAT_UPR",true);assertTrue(f.core.caso(f.a(x.m.upr),c).soloLectura());denied(404,()->flow.requerimiento(f.a(x.m.upr),q));denied(404,()->f.core.detalle(f.a(x.m.upr),com));denied(404,()->f.core.caso(f.a(x.m.upd),c));denied(404,()->flow.requerimiento(f.a(f.headB),q));denied(404,()->flow.requerimiento(f.a(f.legacy),q));assertTrue(flow.requerimientos(f.a(f.headB)).isEmpty());assertTrue(f.core.casos(f.a(f.dist),"",0,20).items().stream().noneMatch(r->r.id().equals(c)));flow.clasificar(f.a(f.headA),UUID.randomUUID(),q,new Clasificacion(1,"ALTA","Alta complejidad profesional"));assertEquals("UPR",flow.requerimiento(f.a(f.headA),q).get("unit_code"));assertEquals("ALTA",flow.requerimiento(f.a(f.headA),q).get("complexity"));x.m.publicar("SUSPENDIDA",f.end);denied(404,()->f.core.caso(f.a(x.m.upr),c));assertNotNull(f.core.caso(f.a(f.profA),c));}
 @Test void destinoConAreaEsObligatorioYTerritorioNoSeInfiereDeRegionAsunto(){var com=x.d.nuevaWeb();denied(409,()->flow.distribuir(f.a(f.dist),UUID.randomUUID(),com,new Encaminar(0,new NuevoDestino("UPR","DEMO_SEDE_A",f.legacy),"Sin área",null)));var sol=flow.distribuir(f.a(f.dist),UUID.randomUUID(),com,new Encaminar(0,new NuevoDestino("UPR","DEMO_SEDE_A",f.headA,"AREA_A"),"Región de domicilio utilizable","REG_LAB_1"));denied(409,()->flow.asumir(f.a(f.headA),UUID.randomUUID(),sol.id(),new Asumir(0,f.profA,"No inventar cobertura","Una justificación no reemplaza cobertura acreditada")));assertEquals(0,x.d.db.sql.queryForObject("SELECT COUNT(*) FROM institution_req",Long.class));}
 @Test void aliasDeLaMismaPersonaNoConfirmaCierreInstitucional()throws Exception{var q=req(x.d.nuevaWeb());var c=flow.abrirCaso(f.a(f.headA),UUID.randomUUID(),q,new Apertura(0,f.profA,"Objetivo propio")).id();f.core.revisarCaso(f.a(f.profA),UUID.randomUUID(),c,new Decision(0,"Solicitud fundada"),"SOLICITUD_TERMINO");String alias=f.user("alias.u2");var r=x.d.mapper.readValue(Base64.getDecoder().decode(x.d.db.sql.queryForObject("SELECT signed_payload FROM authority_batch ORDER BY revision DESC LIMIT 1",String.class)),AutoridadesInstitucionales.Registro12.class);var bindings=new ArrayList<>(r.vinculos());bindings.add(new AutoridadesInstitucionales.Vinculo(alias,"p-"+f.profA,f.start,f.end,ConcesionFixture.huella(x.d.db,alias)));f.importar(new AutoridadesInstitucionales.Registro12("1.2",r.revision()+1,x.clock.instant(),r.expira(),bindings,r.mandatos(),r.areas(),r.ambitos(),r.cambiosArea(),r.materias(),r.sedesRegionales(),r.ambitosMateria()));f.otorgar(alias,"COORDINADOR","AREA_A");denied(409,()->f.core.revisarCaso(f.a(alias),UUID.randomUUID(),c,new Decision(1,"Misma persona en otra cuenta"),"CIERRE"));f.core.revisarCaso(f.a(f.headA),UUID.randomUUID(),c,new Decision(1,"Revisión de otra persona habilitada"),"CIERRE");assertEquals("ACTIVO",flow.requerimiento(f.a(f.headA),q).get("state"));}
}
